"""Typed conversation messages and their JSON wire encoders and decoders."""
from __future__ import annotations

from dataclasses import dataclass, field

from .jsontypes import Json, JsonObject, is_json_object


@dataclass
class ToolCall:
    id: str
    name: str
    arguments: JsonObject = field(default_factory=dict)


@dataclass
class SystemMessage:
    content: str
    role: str = "system"


class _Turn:
    content: str | None
    tool_calls: list[ToolCall] | None

    def is_tool_call(self) -> bool:
        return bool(self.tool_calls)

    def has_text_content(self) -> bool:
        return bool(self.content and self.content.strip())


@dataclass
class UserMessage(_Turn):
    content: str | None = None
    role: str = "user"
    tool_calls: list[ToolCall] | None = None


@dataclass
class AssistantMessage(_Turn):
    content: str | None = None
    role: str = "assistant"
    tool_calls: list[ToolCall] | None = None
    usage: dict[str, int] | None = None


@dataclass
class ToolMessage:
    id: str
    content: str | None = None
    role: str = "tool"
    error: bool = False


@dataclass
class MultiToolMessage:
    tool_messages: list[ToolMessage]
    role: str = "tool"


Message = SystemMessage | UserMessage | AssistantMessage | ToolMessage | MultiToolMessage


def _tool_call_json(call: ToolCall) -> JsonObject:
    return {"id": call.id, "name": call.name, "arguments": call.arguments}


def _tool_message_json(message: ToolMessage) -> JsonObject:
    return {
        "id": message.id,
        "content": message.content,
        "role": message.role,
        "error": message.error,
    }


def to_dict(message: Message) -> JsonObject:
    if isinstance(message, SystemMessage):
        return {"content": message.content, "role": message.role}
    if isinstance(message, ToolMessage):
        return _tool_message_json(message)
    if isinstance(message, MultiToolMessage):
        return {"tool_messages": [_tool_message_json(item) for item in message.tool_messages], "role": message.role}
    value: JsonObject = {
        "content": message.content,
        "role": message.role,
        "tool_calls": None if message.tool_calls is None else [_tool_call_json(call) for call in message.tool_calls],
    }
    if isinstance(message, AssistantMessage):
        usage: Json = None
        if message.usage is not None:
            usage_data: JsonObject = {name: count for name, count in message.usage.items()}
            usage = usage_data
        value["usage"] = usage
    return value


def _string(data: JsonObject, name: str) -> str:
    value = data[name]
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a string")
    return value


def _optional_string(data: JsonObject, name: str) -> str | None:
    value = data.get(name)
    if value is not None and not isinstance(value, str):
        raise TypeError(f"{name} must be a string or null")
    return value


def _arguments(data: JsonObject) -> JsonObject:
    value = data.get("arguments", {})
    if not is_json_object(value):
        raise TypeError("arguments must be an object")
    return value


def _reject_extra(data: JsonObject, accepted: tuple[str, ...], name: str) -> None:
    for key in data:
        if key not in accepted:
            raise TypeError(f"{name}.__init__() got an unexpected keyword argument '{key}'")


def _tool_call(data: JsonObject) -> ToolCall:
    _reject_extra(data, ("id", "name", "arguments"), "ToolCall")
    return ToolCall(_string(data, "id"), _string(data, "name"), _arguments(data))


def _tool_calls(data: JsonObject) -> list[ToolCall] | None:
    value = data.get("tool_calls")
    if value is None:
        return None
    if not isinstance(value, list):
        raise TypeError("tool_calls must be a list")
    calls: list[ToolCall] = []
    for item in value:
        if not isinstance(item, dict):
            raise TypeError("tool_calls must contain objects")
        calls.append(_tool_call(item))
    return calls


def _usage(data: JsonObject) -> dict[str, int] | None:
    value = data.get("usage")
    if value is None:
        return None
    if not isinstance(value, dict):
        raise TypeError("usage must be an object of integer counts")
    usage: dict[str, int] = {}
    for key, count in value.items():
        if not isinstance(key, str) or type(count) is not int:
            raise TypeError("usage must be an object of integer counts")
        usage[key] = count
    return usage


def _role(data: JsonObject, default: str) -> str:
    return _string(data, "role") if "role" in data else default


def _system(data: JsonObject) -> Message:
    _reject_extra(data, ("content", "role"), "SystemMessage")
    return SystemMessage(_string(data, "content"), _role(data, "system"))


def _user(data: JsonObject) -> Message:
    _reject_extra(data, ("content", "role", "tool_calls"), "UserMessage")
    return UserMessage(
        _optional_string(data, "content"),
        _role(data, "user"),
        _tool_calls(data),
    )


def _assistant(data: JsonObject) -> Message:
    _reject_extra(data, ("content", "role", "tool_calls", "usage"), "AssistantMessage")
    return AssistantMessage(
        _optional_string(data, "content"),
        _role(data, "assistant"),
        _tool_calls(data),
        _usage(data),
    )


def _tool_message(data: JsonObject) -> ToolMessage:
    _reject_extra(data, ("id", "content", "role", "error"), "ToolMessage")
    error = data.get("error", False)
    if not isinstance(error, bool):
        raise TypeError("error must be a boolean")
    return ToolMessage(_string(data, "id"), _optional_string(data, "content"), _role(data, "tool"), error)


def _tool(data: JsonObject) -> Message:
    return _tool_message(data)


def _multi_tool(data: JsonObject) -> Message:
    _reject_extra(data, ("tool_messages", "role"), "MultiToolMessage")
    values = data["tool_messages"]
    if not isinstance(values, list) or not all(isinstance(item, dict) for item in values):
        raise TypeError("tool_messages must be a list of objects")
    tool_messages: list[ToolMessage] = []
    for item in values:
        if not isinstance(item, dict):
            raise TypeError("tool_messages must be a list of objects")
        tool_messages.append(_tool_message(item))
    return MultiToolMessage(tool_messages)


_PARSERS = {"system": _system, "user": _user, "assistant": _assistant, "tool": _tool}


def from_dict(data: JsonObject) -> Message:
    if "tool_messages" in data:
        return _multi_tool(data)
    role = data.get("role")
    parser = _PARSERS.get(role, _user) if isinstance(role, str) else _user
    return parser(data)
"""The active workspace context and typed gateways supplied while building an agent."""
from __future__ import annotations

from collections.abc import Callable, Iterator, Mapping, Sequence
from contextlib import contextmanager
from contextvars import ContextVar
from dataclasses import dataclass, field, replace
from pathlib import Path
from typing import TYPE_CHECKING

from .jsontypes import Json, JsonObject
from .messages import AssistantMessage, Message, from_dict, to_dict
from .toolkit import Tool

if TYPE_CHECKING:
    from .billing import Billing


@dataclass(frozen=True)
class ActionInterface:
    available: tuple[Tool, ...]

    def select(self, names: Sequence[str]) -> tuple[Tool, ...]:
        by_name = {tool.name: tool for tool in self.available}
        missing = [name for name in names if name not in by_name]
        if missing:
            raise ValueError(f"Unknown actions: {missing}")
        return tuple(by_name[name] for name in names)


@dataclass(frozen=True)
class KitResources:
    root: Path
    files: tuple[str, ...]

    @classmethod
    def from_root(cls, root: Path) -> KitResources:
        root = root.resolve()
        files = tuple(
            path.relative_to(root).as_posix()
            for path in sorted(root.rglob("*"))
            if path.is_file() and "__pycache__" not in path.parts
        )
        return cls(root, files)

    def path(self, relative_path: str) -> Path:
        candidate = (self.root / relative_path).resolve()
        if not candidate.is_relative_to(self.root):
            raise ValueError(f"Path escapes the kit root: {relative_path!r}")
        return candidate

    def read_text(self, relative_path: str) -> str:
        return self.path(relative_path).read_text()


@dataclass(frozen=True)
class ModelConfig:
    model: str
    constraints: Mapping[str, Json] = field(default_factory=dict)


def _single_config(models: Sequence[ModelConfig], model: str) -> ModelConfig:
    matches = [config for config in models if config.model == model]
    if not matches:
        allowed = ", ".join(repr(config.model) for config in models)
        raise ValueError(f"Model {model!r} is not allowed; choose one of {allowed}")
    if len(matches) > 1:
        raise ValueError(f"Model {model!r} has several configurations; not supported")
    return matches[0]


def _constraint_choices(expected: Json) -> list[Json] | None:
    if not isinstance(expected, dict):
        return None
    choices = expected.get("one_of")
    return choices if isinstance(choices, list) else None


def _resolve_constraint(name: str, expected: Json, kwargs: Mapping[str, Json], resolved: JsonObject) -> None:
    choices = _constraint_choices(expected)
    if choices is not None:
        if kwargs.get(name) not in choices:
            raise ValueError(f"{name} must be chosen from {choices!r}")
        return
    if name in kwargs and kwargs[name] != expected:
        raise ValueError(f"{name} must be {expected!r}, got {kwargs[name]!r}")
    resolved[name] = expected


def resolve_call(
    models: Sequence[ModelConfig], model: str, kwargs: Mapping[str, Json]
) -> JsonObject:
    """Apply pinned constraints, require explicit choices, reject conflicts."""
    config = _single_config(models, model)
    request_args: JsonObject = {}
    for name, expected in config.constraints.items():
        _resolve_constraint(name, expected, kwargs, request_args)
    request_args.update(kwargs)
    return request_args


@dataclass
class ModelGateway:
    models: tuple[ModelConfig, ...]
    _send: Callable[[JsonObject], JsonObject]
    embedding_models: tuple[ModelConfig, ...] = ()

    def embed(self, *, model: str, inputs: Sequence[str], **kwargs: Json) -> list[list[float]]:
        """One vector per input, in order, from an allowed embedding model."""
        reply = self._send(
            {
                "call": "embed",
                "model": model,
                "inputs": list(inputs),
                "kwargs": resolve_call(self.embedding_models, model, kwargs),
            }
        )
        vectors = reply.get("vectors")
        if not isinstance(vectors, list):
            raise RuntimeError("embedding gateway returned invalid vectors")
        parsed: list[list[float]] = []
        for vector in vectors:
            if not isinstance(vector, list):
                raise RuntimeError("embedding gateway returned invalid vectors")
            parsed_vector: list[float] = []
            for value in vector:
                if isinstance(value, bool) or not isinstance(value, (int, float)):
                    raise RuntimeError("embedding gateway returned invalid vectors")
                parsed_vector.append(float(value))
            parsed.append(parsed_vector)
        return parsed

    def generate(
        self,
        *,
        model: str,
        messages: list[Message],
        actions: Sequence[Tool] | None = None,
        tool_choice: Json = None,
        **kwargs: Json,
    ) -> AssistantMessage:
        reply = self._send(
            {
                "call": "model",
                "model": model,
                "messages": [to_dict(message) for message in messages],
                "tools": [tool.openai_schema for tool in actions] if actions else None,
                "tool_choice": tool_choice,
                "kwargs": resolve_call(self.models, model, kwargs),
            }
        )
        raw_message = reply.get("message")
        if not isinstance(raw_message, dict):
            raise RuntimeError("model gateway returned an invalid message")
        message = from_dict(raw_message)
        if not isinstance(message, AssistantMessage):
            raise RuntimeError("model gateway returned a non-assistant message")
        if message.is_tool_call() and message.has_text_content():
            # Models often narrate before calling a tool. A turn is either text to the
            # customer or tool calls, never both; the tool calls carry the work.
            message = replace(message, content=None)
        return message


@dataclass(frozen=True)
class AgentBuildContext:
    action_interface: ActionInterface
    resources: KitResources
    model_gateway: ModelGateway
    runtime_config: Mapping[str, str]
    billing: Billing | None = None


_active: ContextVar[AgentBuildContext | None] = ContextVar("agent_context", default=None)


@contextmanager
def activate_agent_context(context: AgentBuildContext) -> Iterator[None]:
    token = _active.set(context)
    try:
        yield
    finally:
        _active.reset(token)


def get_agent_context() -> AgentBuildContext:
    context = _active.get()
    if context is None:
        raise RuntimeError("Agent context is only available while create_agent() is executing")
    return context
"""Typed client interface to the Redwood billing record store."""
from __future__ import annotations

import json
import socket
from collections.abc import Callable
from enum import StrEnum

from ..jsontypes import Json, JsonObject, is_json_object

PRACTICE_SOCKET = "/run/redwood/practice-console.sock"


class Op(StrEnum):
    DESCRIBE = "describe"
    QUERY = "query"
    INSERT = "insert"
    UPDATE = "update"


class ErrorCode(StrEnum):
    INVALID_REQUEST = "invalid_request"
    UNKNOWN_FIELD = "unknown_field"
    MISSING_FIELDS = "missing_fields"
    NOT_FOUND = "not_found"
    READ_ONLY = "read_only"
    NOT_DRAFT = "not_draft"
    CLOSED = "closed"
    BUSINESS_RULE = "business_rule"


class BillingError(RuntimeError):
    """An error returned by the billing console.

    `code` is the console's ErrorCode, or None when the request never reached the console.
    """

    def __init__(self, message: str) -> None:
        super().__init__(message)
        prefix = message.partition(": ")[0]
        self.code = ErrorCode(prefix) if prefix in set(ErrorCode) else None


class Billing:
    def __init__(self, send: Callable[[JsonObject], JsonObject]) -> None:
        self._send = send

    def _call(self, op: Op, **fields: Json) -> JsonObject:
        try:
            reply = self._send({"call": "billing", "op": op, **fields})
        except RuntimeError as error:
            raise BillingError(str(error)) from None
        return {key: value for key, value in reply.items() if key != "ok"}

    def describe(self) -> JsonObject:
        """Return table and field descriptors."""
        return self._call(Op.DESCRIBE)

    def query(self, table: str, where: JsonObject | None = None, cursor: str | None = None) -> JsonObject:
        """Return a page of rows matching field values."""
        return self._call(Op.QUERY, table=table, where=where, cursor=cursor)

    def insert(self, table: str, row: JsonObject) -> JsonObject:
        """Insert a row and return the stored record."""
        return self._call(Op.INSERT, table=table, row=row)

    def update(self, table: str, row_id: str, changes: JsonObject) -> JsonObject:
        """Update a row and return the stored record."""
        return self._call(Op.UPDATE, table=table, row_id=row_id, changes=changes)


def reply_body(reply: object) -> JsonObject:
    """Return a console reply's body, or raise its error for `Billing` to rewrap."""
    if not is_json_object(reply):
        raise RuntimeError("practice console sent a malformed reply")
    if reply.get("ok") is not True:
        raise RuntimeError(str(reply.get("error", "practice console rejected the request")))
    return reply


def development_billing(socket_path: str = PRACTICE_SOCKET) -> Billing:
    """A fresh practice console over synthetic records for the current release; writes are discarded."""
    connection = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    connection.connect(socket_path)
    stream = connection.makefile("rw", encoding="utf-8")

    def send(request: JsonObject) -> JsonObject:
        stream.write(json.dumps(request) + "\n")
        stream.flush()
        return reply_body(json.loads(stream.readline() or "null"))

    return Billing(send)
