import corpus, collections
tot=collections.Counter(); dense=collections.Counter(); nd=0; na=0; chars=0
for rel,rec,raw in corpus.iter_records():
    ch=corpus.chunk_record(rel,rec)
    p=rel.split('/')[0]
    tot[p]+=len(ch)
    if corpus.in_billing_scope(rel,rec,raw):
        dense[p]+=len(ch); nd+=1; chars+=sum(len(c['body']) for c in ch)
    na+=1
print(tot, sum(tot.values())); print(dense, sum(dense.values()), nd, na, chars)
